import type AxeBuilder from "@axe-core/playwright";
import type { Page } from "@playwright/test";
import { animationsFinished, expect, test } from "./fixtures";

// Loading the engine means fetching and compiling ~35 MB of WebAssembly.
const ENGINE_TIMEOUT = 60_000;
// Samples are generated by the engine when they're loaded; the telemetry is 80,000 rows.
const SAMPLE_TIMEOUT = 30_000;
// Even small queries can take seconds in WebKit on a busy machine.
const QUERY_TIMEOUT = 20_000;
// Each test loads the engine and runs several full-page scans, which take seconds each in Firefox.
const FLOW_TIMEOUT = 120_000;

/** A small result with a text and a number column, so it can be charted. */
const READINGS =
  "SELECT range AS id, 'M' || (range % 4) AS machine, range * 1.5 AS output FROM range(20)";

const editor = (page: Page) => page.getByRole("textbox", { name: "SQL editor" });
const summary = (page: Page) => page.getByRole("region", { name: "Query" }).getByText(/ in \d/);

async function openWorkbench(page: Page) {
  await page.goto("/app/");
  await expect(page.getByRole("status")).toHaveText(/^Engine ready/, { timeout: ENGINE_TIMEOUT });
}

/** Replaces the editor's contents with `sql` and runs it. */
async function run(page: Page, sql: string) {
  await editor(page).click();
  await page.keyboard.press("ControlOrMeta+A");
  await page.keyboard.type(sql);
  await page.keyboard.press("ControlOrMeta+Enter");
}

/**
 * Runs the scan once the page has settled (colours measured mid-fade are wrong), and lists each
 * violation with the elements it was found on.
 */
async function expectNoViolations(page: Page, scan: AxeBuilder, state: string) {
  await animationsFinished(page);
  const { violations } = await scan.analyze();
  const found = violations.map(({ id, nodes }) => ({
    id,
    nodes: nodes.map(({ target }) => target.join(" ")),
  }));
  expect(found, `axe violations with ${state}`).toEqual([]);
}

/**
 * Full-page axe scans of the workbench at each state of its core flows, for one system colour
 * scheme. Each `accessibility.<scheme>.spec.ts` file applies `colorSchemeOptions()` at the top
 * level (it sets browser launch options, which Playwright only allows there) and then registers
 * these tests.
 */
export function accessibilityTests(colorScheme: "light" | "dark") {
  test.describe(`accessibility of the core flows (${colorScheme})`, () => {
    test("loading sample data and browsing its tables", async ({ page, makeAxeBuilder }) => {
      test.setTimeout(FLOW_TIMEOUT);
      await openWorkbench(page);
      await expectNoViolations(page, makeAxeBuilder(), "an empty workbench");

      await page.getByRole("button", { name: "Load sample data" }).click();
      const samples = page.getByRole("dialog", { name: "Load sample data" });
      await expect(samples).toBeVisible();
      await expectNoViolations(page, makeAxeBuilder(), "the sample data dialog open");
      await samples.getByRole("button", { name: /^Machine telemetry/ }).click();
      await expect(samples).toBeHidden({ timeout: SAMPLE_TIMEOUT });
      await expectNoViolations(page, makeAxeBuilder(), "a sample loaded");

      const tree = page.getByRole("tree", { name: "Tables" });
      await tree.getByRole("treeitem", { name: /^machine_telemetry/ }).focus();
      await page.keyboard.press("ArrowRight");
      await expect(tree.getByRole("treeitem").nth(1)).toBeVisible();
      // Expanded, a table's tree item holds its columns' tree items, as the ARIA tree pattern
      // nests them, and axe counts their text as the table's visible label. The table's name was
      // checked against its label above, collapsed.
      await expectNoViolations(
        page,
        makeAxeBuilder().disableRules(["label-content-name-mismatch"]),
        "a sample's columns shown",
      );
    });

    test("reading, exporting and charting a result", async ({ page, makeAxeBuilder }) => {
      test.setTimeout(FLOW_TIMEOUT);
      await openWorkbench(page);
      await run(page, READINGS);
      await expect(summary(page)).toHaveText(/^20 rows in /, { timeout: QUERY_TIMEOUT });
      const grid = page.getByRole("grid", { name: "Results" });
      await grid.focus();
      await page.keyboard.press("Shift+ArrowDown");
      await expect(grid).toHaveAttribute("aria-activedescendant", /.+/);
      await expectNoViolations(page, makeAxeBuilder(), "results shown and a selection made");

      await page.getByRole("button", { name: "Export as CSV" }).click();
      await expect(page.getByText(/^Downloaded /)).toBeVisible();
      await expectNoViolations(page, makeAxeBuilder(), "a result exported");

      await page.getByRole("button", { name: "Chart", exact: true }).click();
      await expect(page.getByRole("img", { name: /^Bar chart of / })).toBeVisible();
      await expectNoViolations(page, makeAxeBuilder(), "a chart shown");
      await page.getByRole("button", { name: "View as table" }).click();
      await expect(page.getByRole("table")).toBeVisible();
      await expectNoViolations(page, makeAxeBuilder(), "a chart shown as a table");
    });

    test("browsing templates", async ({ page, makeAxeBuilder }) => {
      test.setTimeout(FLOW_TIMEOUT);
      await openWorkbench(page);
      await page.getByRole("button", { name: "Templates" }).click();
      const templates = page.getByRole("dialog", { name: "Templates" });
      await expect(templates).toBeVisible();
      await expectNoViolations(page, makeAxeBuilder(), "the templates dialog open");
      await templates.getByRole("button", { name: /^Reject rate by machine/ }).click();
      await expect(page.getByRole("dialog", { name: "Reject rate by machine" })).toBeVisible();
      await expectNoViolations(page, makeAxeBuilder(), "a template's form open");
      await page.keyboard.press("Escape");
      await expect(page.getByRole("dialog")).toBeHidden();
    });

    test("history, saved queries and errors", async ({ page, makeAxeBuilder }) => {
      test.setTimeout(FLOW_TIMEOUT);
      await openWorkbench(page);
      await run(page, READINGS);
      await expect(summary(page)).toHaveText(/^20 rows in /, { timeout: QUERY_TIMEOUT });
      await run(page, "SELECT 42 AS answer");
      await expect(summary(page)).toHaveText(/^1 row in /, { timeout: QUERY_TIMEOUT });
      await expect(
        page.getByRole("list", { name: "Query history" }).getByRole("listitem"),
      ).toHaveCount(2);
      await expectNoViolations(page, makeAxeBuilder(), "history populated");
      await page.getByRole("button", { name: "Saved" }).click();
      await page.getByRole("textbox", { name: "Name" }).fill("Answer");
      await page.getByRole("button", { name: "Save", exact: true }).click();
      await expect(
        page.getByRole("list", { name: "Saved queries" }).getByRole("listitem"),
      ).toHaveCount(1);
      await expectNoViolations(page, makeAxeBuilder(), "a query saved");

      await run(page, "SELECT answr FROM (SELECT 42 AS answer)");
      await expect(page.getByRole("alert")).toBeVisible();
      await expectNoViolations(page, makeAxeBuilder(), "an error shown");
    });
  });
}
